function loadSave(){try{const x=JSON.parse(storage.get(SAVE_KEY)||'null');return normalize(x)}catch{return defaults()}}
function normalize(x){const d=defaults(),caps={hull:3,speed:2,recovery:2,lastStand:1,damage:3,crit:2,chipTech:2,overcharge:1,cooldown:3,salvage:3,magnetism:2,coreHunter:1},sectorRanks={outer:1,debris:3,crimson:6};if(!x||typeof x!=='object')return d;const out={...d,...x};out.settings={...d.settings,...(x.settings||{})};out.weapons={...d.weapons,...(x.weapons||{})};out.ships={...d.ships,...(x.ships||{})};out.modules={...d.modules,...(x.modules||{})};out.skills={...d.skills,...(x.skills||{})};out.loadout={...d.loadout,...(x.loadout||{})};out.stats={...d.stats,...(x.stats||{})};out.sectorProgress={...d.sectorProgress,...(x.sectorProgress||{})};if(!['de','en'].includes(out.language))out.language='de';for(const id of Object.keys(d.weapons)){out.weapons[id]={...d.weapons[id],...(out.weapons[id]||{})};out.weapons[id].unlocked=Boolean(out.weapons[id].unlocked);out.weapons[id].level=Math.max(out.weapons[id].unlocked?1:0,Math.min(5,Math.floor(Number(out.weapons[id].level)||0)))}for(const id of Object.keys(d.ships)){out.ships[id]={...d.ships[id],...(out.ships[id]||{})};out.ships[id].unlocked=Boolean(out.ships[id].unlocked);out.ships[id].level=Math.max(out.ships[id].unlocked?1:0,Math.min(5,Math.floor(Number(out.ships[id].level)||0)))}for(const id of Object.keys(d.modules)){out.modules[id]={...d.modules[id],...(out.modules[id]||{})};out.modules[id].unlocked=Boolean(out.modules[id].unlocked);out.modules[id].level=Math.max(out.modules[id].unlocked?1:0,Math.min(5,Math.floor(Number(out.modules[id].level)||0)))}for(const id of Object.keys(d.skills))out.skills[id]=Math.max(0,Math.min(caps[id]||3,Math.floor(Number(out.skills[id])||0)));for(const id of Object.keys(d.stats))out.stats[id]=Math.max(0,Math.floor(Number(out.stats[id])||0));for(const id of Object.keys(d.sectorProgress))out.sectorProgress[id]=Math.max(0,Math.floor(Number(out.sectorProgress[id])||0));out.credits=Math.max(0,Math.floor(Number(out.credits)||0));out.cores=Math.max(0,Math.floor(Number(out.cores)||0));out.best=Math.max(0,Math.floor(Number(out.best)||0));out.explorationBest=Math.max(0,Math.floor(Number(out.explorationBest)||0));out.skillPoints=Math.max(0,Math.floor(Number(out.skillPoints)||0));out.pilotXp=Math.max(0,Math.floor(Number(out.pilotXp)||0));out.pilotRank=pilotRankForXp(out.pilotXp);out.adaptiveAssist=Math.max(0,Math.min(3,Math.floor(Number(out.adaptiveAssist)||0)));out.techPity=Math.max(0,Math.min(3,Math.floor(Number(out.techPity)||0)));out.settings.screenShake=out.settings.screenShake!==false;out.settings.autoPause=out.settings.autoPause!==false;out.settings.radar=out.settings.radar!==false;if(!['explorer','operation','veteran'].includes(out.difficulty))out.difficulty='explorer';if(!sectorRanks[out.selectedSector]||out.pilotRank<sectorRanks[out.selectedSector])out.selectedSector='outer';if(!out.ships[out.loadout.ship]?.unlocked)out.loadout.ship='vanguard';if(!out.weapons[out.loadout.primary]?.unlocked)out.loadout.primary='laser';if(out.loadout.secondary&&!out.weapons[out.loadout.secondary]?.unlocked)out.loadout.secondary=null;if(out.loadout.secondary===out.loadout.primary)out.loadout.secondary=null;if(out.loadout.module&&!out.modules[out.loadout.module]?.unlocked)out.loadout.module='targeting';out.version=CONFIG.version;return out}
function persist(){storage.set(SAVE_KEY,JSON.stringify(save));renderHangar()}

