function rankThreshold(rank){const n=Math.max(0,rank-1);return Math.round(70*n+38*n*n)}
function pilotRankForXp(value){let rank=1;while(value>=rankThreshold(rank+1)&&rank<60)rank++;return rank}
function rankRewardFor(rank){return{credits:100+rank*35,cores:rank%3===0?1:0,skills:rank%2===0?1:0}}
function requirementsMet(list=[]){return list.every(req=>(save.skills[req.id]||0)>=req.rank)}
function requirementText(list=[]){const q=t();return list.map(req=>`${q.skillNames[req.id]} ${req.rank}`).join(' + ')}
function renderProgressionUI(){const q=t(),rank=pilotRankForXp(save.pilotXp),start=rankThreshold(rank),end=rankThreshold(rank+1),progress=Math.max(0,Math.min(1,(save.pilotXp-start)/Math.max(1,end-start)));save.pilotRank=rank;$('pilotRankValue').textContent=rank;$('pilotXpFill').style.width=(progress*100)+'%';$('pilotXpText').textContent=`${save.pilotXp-start} / ${end-start} ${q.pilotXp}`;const reward=rankRewardFor(rank+1);$('rankRewardText').textContent=`${q.rankReward}: ${reward.credits} ${q.credits}${reward.cores?` · ${reward.cores} ${q.cores}`:''}${reward.skills?` · ${reward.skills} ${q.skillPoints}`:''}`;$('rookieProtection').textContent=(save.stats.runs||0)<5?q.newPilot:'';const select=$('difficultySelect');select.value=save.difficulty;for(const option of select.options)option.textContent=q.difficultyNames[option.value];$('difficultyDescription').textContent=q.difficultyDesc[save.difficulty];$('sectorMap').innerHTML='';for(const [id,def] of Object.entries(sectorDefs)){const locked=rank<def.rank,button=document.createElement('button');button.type='button';button.className='sector-node '+id+(save.selectedSector===id?' selected':'')+(locked?' locked':'');button.dataset.sector=id;button.disabled=locked;button.innerHTML=`<span>${q.sectorNames[id]}</span><strong>${locked?q.lockedRank+' '+def.rank:q.bestWave+' '+Math.max(1,save.sectorProgress[id]||1)}</strong><small>${q.sectorDesc[id]}</small><i>x${def.reward.toFixed(2)} ${q.earned}</i>`;$('sectorMap').append(button)}const selected=sectorDefs[save.selectedSector];$('sectorRewardText').textContent=`${q.sectorNames[save.selectedSector]} · x${(selected.reward*difficultyDefs[save.difficulty].reward).toFixed(2)} ${q.earned}`}
function renderSkillTree(){const q=t(),grid=$('skillGrid');grid.innerHTML='';for(const branch of ['combat','survival','systems']){const lane=document.createElement('section');lane.className='skill-branch '+branch;lane.innerHTML=`<header><span>${q.branchNames[branch]}</span></header><div class="skill-lane"></div>`;const list=lane.querySelector('.skill-lane');for(const [id,node] of Object.entries(skillTree))if(node.branch===branch)list.append(skillCard(id));grid.append(lane)}}
function selectSector(id){const def=sectorDefs[id];if(!def||save.pilotRank<def.rank)return;save.selectedSector=id;persist()}
function selectDifficulty(id){if(!difficultyDefs[id])return;save.difficulty=id;persist()}

function canPay(cost){return save.credits>=cost.c&&save.cores>=cost.k}function pay(cost){save.credits-=cost.c;save.cores-=cost.k}
function levelCost(kind,id,level){const src=kind==='weapon'?weapons[id]:kind==='ship'?ships[id]:modules[id];return{c:src.upgrade[level-1]||0,k:level>=3?1:0}}
function buySkill(id){const node=skillTree[id],rank=save.skills[id]||0;if(!node||rank>=node.max||save.skillPoints<node.cost||!requirementsMet(node.requires))return;save.skillPoints-=node.cost;save.skills[id]=rank+1;persist()}
function unlock(kind,id){const src=kind==='weapon'?weapons[id]:kind==='ship'?ships[id]:modules[id],cost=src.unlock;if(!canPay(cost))return;pay(cost);const bucket=kind==='weapon'?save.weapons:kind==='ship'?save.ships:save.modules;bucket[id]={unlocked:true,level:1};persist()}
function upgradePermanent(kind,id){const bucket=kind==='weapon'?save.weapons:kind==='ship'?save.ships:save.modules,entry=bucket[id];if(!entry.unlocked||entry.level>=5)return;const cost=levelCost(kind,id,entry.level);if(!canPay(cost))return;pay(cost);entry.level++;persist()}
function equipWeapon(id,slot){if(!save.weapons[id].unlocked)return;if(slot==='secondary'&&save.loadout.primary===id)save.loadout.primary=save.loadout.secondary||'laser';if(slot==='primary'&&save.loadout.secondary===id)save.loadout.secondary=save.loadout.primary;save.loadout[slot]=id;if(save.loadout.primary===save.loadout.secondary)save.loadout.secondary=null;persist()}
function equipShip(id){if(save.ships[id].unlocked){save.loadout.ship=id;persist()}}function equipModule(id){if(save.modules[id].unlocked){save.loadout.module=id;persist()}}

function renderHangar(){const q=t();document.documentElement.lang=save.language;document.title=q.title;$('langDe').classList.toggle('active',save.language==='de');$('langEn').classList.toggle('active',save.language==='en');$('hangarTitle').textContent=q.hangar;$('hangarSubtitle').textContent=q.hangarSub;$('creditsValue').textContent=save.credits;$('creditsLabel').textContent=q.credits;$('coresValue').textContent=save.cores;$('coresLabel').textContent=q.cores;$('bestValue').textContent=save.best;$('hangarBestLabel').textContent=q.best;$('tabDeployment').textContent=q.deployment;$('tabWeapons').textContent=q.weapons;$('tabShips').textContent=q.ships;$('tabModules').textContent=q.modules;$('tabSkills').textContent=q.skills;$('tabData').textContent=q.data;$('skillPointsValue').textContent=save.skillPoints;$('skillPointsLabel').textContent=q.skillPoints;$('shipSlotLabel').textContent=q.ship;$('primarySlotLabel').textContent=q.primary;$('secondarySlotLabel').textContent=q.secondary;$('moduleSlotLabel').textContent=q.module;$('shipSlot').textContent=q.shipNames[save.loadout.ship];$('primarySlot').textContent=q.weaponNames[save.loadout.primary];$('secondarySlot').textContent=save.loadout.secondary?q.weaponNames[save.loadout.secondary]:q.none;$('moduleSlot').textContent=save.loadout.module?q.moduleNames[save.loadout.module]:q.none;$('economyNote').textContent=q.economy;$('startRunBtn').textContent=q.start;$('exportTitle').textContent=q.exportTitle;$('exportText').textContent=q.exportText;$('refreshExportBtn').textContent=q.refresh;$('importTitle').textContent=q.importTitle;$('importText').textContent=q.importText;$('importBtn').textContent=q.import;$('resetSaveBtn').textContent=q.reset;$('progressHint').textContent=q.progress;$('careerStats').textContent=q.career(save.stats);if($('explorationRecordValue'))$('explorationRecordValue').textContent=Math.round(save.explorationBest||0);if($('explorationRecordDiscoveries'))$('explorationRecordDiscoveries').textContent=save.stats.discoveries||0;$('exportArea').value=btoa(unescape(encodeURIComponent(JSON.stringify(save))));
 const icon=$('shipIcon');icon.className='ship-icon '+(save.loadout.ship==='vanguard'?'':save.loadout.ship);
 $('weaponGrid').innerHTML='';for(const id of Object.keys(weapons))$('weaponGrid').appendChild(weaponCard(id));
 $('shipGrid').innerHTML='';for(const id of Object.keys(ships))$('shipGrid').appendChild(shipCard(id));
 $('moduleGrid').innerHTML='';for(const id of Object.keys(modules))$('moduleGrid').appendChild(moduleCard(id));renderSkillTree();renderProgressionUI();
}
function priceText(cost){return `${cost.c} ${t().credits}${cost.k?` + ${cost.k} ${t().cores}`:''}`}
function pips(level){return '◆'.repeat(level)+'◇'.repeat(Math.max(0,5-level))}
function itemVisual(kind,id){return `<div class="item-visual ${kind}-visual ${id}" aria-hidden="true"><span></span><i></i><b></b></div>`}
function weaponCard(id){const q=t(),entry=save.weapons[id],d=document.createElement('article');d.className='card item-card weapon-card '+id+' '+(!entry.unlocked?'locked ':'')+((save.loadout.primary===id||save.loadout.secondary===id)?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('weapon',id,entry.level):weapons[id].unlock;d.innerHTML=itemVisual('weapon',id)+'<div class="item-copy"><h3>'+q.weaponNames[id]+'</h3><div class="level-pips">'+pips(entry.level)+'</div><p>'+q.weaponDesc[id]+'</p><div class="tag-row"><span class="tag strong">'+q.strong+': '+q.strongTexts[id]+'</span><span class="tag weak">'+q.weak+': '+q.weakTexts[id]+'</span></div><div class="mechanic-note evolution-note"><b>'+q.evolution+'</b><span>'+q.weaponEvolutionDesc[id]+'</span></div><div class="muted">'+(entry.unlocked?(entry.level>=5?q.max:q.cost+': '+priceText(cost)):q.cost+': '+priceText(cost))+'</div></div>';const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked){a.append(btn(q.buy,()=>unlock('weapon',id),!canPay(cost),'gold'))}else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('weapon',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.primary===id?q.equippedPrimary:q.equipPrimary,()=>equipWeapon(id,'primary'),save.loadout.primary===id));a.append(btn(save.loadout.secondary===id?q.equippedSecondary:q.equipSecondary,()=>equipWeapon(id,'secondary'),save.loadout.secondary===id))}d.append(a);return d}
function shipCard(id){const q=t(),entry=save.ships[id],d=document.createElement('article');d.className='card item-card ship-card '+id+' '+(!entry.unlocked?'locked ':'')+(save.loadout.ship===id?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('ship',id,entry.level):ships[id].unlock,s=ships[id].stats;d.innerHTML=itemVisual('ship',id)+'<div class="item-copy"><h3>'+q.shipNames[id]+'</h3><div class="level-pips">'+pips(entry.level)+'</div><p>'+q.shipDesc[id]+'</p><div class="stat-bars"><label>HP <i style="--v:'+Math.min(100,s.hp/1.7)+'%"></i></label><label>SPD <i style="--v:'+Math.min(100,s.speed/4.1)+'%"></i></label><label>SHD <i style="--v:'+Math.min(100,s.shield*1.8)+'%"></i></label></div><div class="mechanic-note passive-note"><b>'+q.passive+'</b><span>'+q.shipPassiveDesc[id]+'</span></div><div class="muted">'+(entry.unlocked?(entry.level>=5?q.max:q.cost+': '+priceText(cost)):q.cost+': '+priceText(cost))+'</div></div>';const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked)a.append(btn(q.buy,()=>unlock('ship',id),!canPay(cost),'gold'));else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('ship',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.ship===id?q.equipped:q.equip,()=>equipShip(id),save.loadout.ship===id))}d.append(a);return d}
function moduleCard(id){const q=t(),entry=save.modules[id],d=document.createElement('article');d.className='card item-card module-card '+id+' '+(!entry.unlocked?'locked ':'')+(save.loadout.module===id?'selected':'');const cost=entry.unlocked&&entry.level<5?levelCost('module',id,entry.level):modules[id].unlock;d.innerHTML=itemVisual('module',id)+'<div class="item-copy"><h3>'+q.moduleNames[id]+'</h3><div class="level-pips">'+pips(entry.level)+'</div><p>'+q.moduleDesc[id]+'</p><div class="module-signal"><i></i><i></i><i></i><i></i></div><div class="mechanic-note synergy-note"><b>'+q.synergy+'</b><span>'+q.moduleSynergyDesc[id]+'</span></div><div class="muted">'+(entry.unlocked?(entry.level>=5?q.max:q.cost+': '+priceText(cost)):q.cost+': '+priceText(cost))+'</div></div>';const a=document.createElement('div');a.className='card-actions';if(!entry.unlocked)a.append(btn(q.buy,()=>unlock('module',id),!canPay(cost),'gold'));else{a.append(btn(entry.level>=5?q.max:q.upgrade,()=>upgradePermanent('module',id),entry.level>=5||!canPay(cost),'gold'));a.append(btn(save.loadout.module===id?q.equipped:q.equip,()=>equipModule(id),save.loadout.module===id))}d.append(a);return d}
function skillCard(id){const q=t(),node=skillTree[id],rank=save.skills[id]||0,locked=!requirementsMet(node.requires),d=document.createElement('article');d.className='skill-node '+node.branch+(locked?' locked':'')+(rank>=node.max?' mastered':'');d.dataset.skill=id;d.dataset.tier=node.tier;const req=locked?`<div class="skill-requirement">${q.requires}: ${requirementText(node.requires)}</div>`:'';d.innerHTML=`<div class="skill-orb"><span>${node.tier}</span></div><div class="skill-copy"><h3>${q.skillNames[id]}</h3><div class="level-pips">${'◆'.repeat(rank)+'◇'.repeat(node.max-rank)}</div><p>${q.skillDesc[id]}</p>${req}<div class="muted">${q.rank} ${rank} / ${node.max} · ${node.cost} ${node.cost===1?q.skillPoint:q.skillPoints}</div></div>`;const a=document.createElement('div');a.className='card-actions';a.append(btn(rank>=node.max?q.max:q.learn,()=>buySkill(id),rank>=node.max||locked||save.skillPoints<node.cost,'gold'));d.append(a);return d}
function btn(text,fn,disabled=false,cls=''){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=disabled;b.className='small '+cls;b.addEventListener('click',fn);return b}

