function refreshActiveWorld(cx,cy){const next=new Set(),objects=[];for(let x=cx-WORLD_RADIUS;x<=cx+WORLD_RADIUS;x++)for(let y=cy-WORLD_RADIUS;y<=cy+WORLD_RADIUS;y++){const chunk=generateChunk(x,y);chunk.lastSeen=elapsed;next.add(chunk.key);for(const o of chunk.objects)if(!(o.type==='asteroid'&&o.dead))objects.push(o)}activeChunkKeys=next;worldObjects=objects;trimWorldCache(cx,cy)}
