function startRun(){resetRun();state='running';$('hangar').classList.add('hidden');$('hud').classList.remove('hidden');$('gameOverOverlay').classList.add('hidden');$('pauseOverlay').classList.add('hidden');$('upgradeOverlay').classList.add('hidden');last=performance.now();showToast(t().sectorNames[save.selectedSector]+' // '+t().difficultyNames[save.difficulty],1);requestAnimationFrame(()=>canvas.focus())}
